CAT = "aereraRegister"; SEG = "REG"
# Bylaw No. (85) of 2006 Regulating the Real Estate Brokers Register (Chapters One, Two, Six, Seven)
# and the RERA Real Estate Brokerage Practice Guide (Nov 2024) on the broker card.
